using System;using System.Collections.Generic;public class SuffixTree{private class Node{public Dictionary<char, Node> Children = new Dictionary<char, Node>();public int Start;public int* End;public int Length;public Node(int start, int* end, int length){Start = start;End = end;Length = length;}}private readonly string _text;private readonly Node _root;public SuffixTree(string text){_text = text;_root = new Node(-1, null, 0);BuildSuffixTree();}private void BuildSuffixTree(){for (int i = 0; i < _text.Length; i++){InsertSuffix(i);}}private void InsertSuffix(int index){Node currentNode = _root;int currentIndex = index;while (currentIndex < _text.Length){if (!currentNode.Children.ContainsKey(_text[currentIndex])){currentNode.Children[_text[currentIndex]] = new Node(currentIndex, null, _text.Length - currentIndex);}currentNode = currentNode.Children[_text[currentIndex]];currentIndex++;}}public bool Search(string pattern){Node currentNode = _root;int index = 0;while (index < pattern.Length){if (!currentNode.Children.ContainsKey(pattern[index])){return false;}currentNode = currentNode.Children[pattern[index]];index++;}return true;}public List<int> FindOccurrences(string pattern){List<int> occurrences = new List<int>();Node currentNode = _root;int index = 0;while (index < pattern.Length){if (!currentNode.Children.ContainsKey(pattern[index])){return occurrences;}currentNode = currentNode.Children[pattern[index]];index++;}FindAllLeafOccurrences(currentNode, occurrences);return occurrences;}private void FindAllLeafOccurrences(Node node, List<int> occurrences){if (node == null){return;}if (node.End == null){occurrences.Add(node.Start);}foreach (var child in node.Children.Values){FindAllLeafOccurrences(child, occurrences);}}}